mapper.select:
SELECT FROM forum_post p INNER JOIN member m ON m.id = p.author_id LEFT JOIN forum_category c ON c.id = p.category_id WHERE p.deleted = 0
AND p.status = #{status}
AND p.author_id = #{authorId}
AND p.status = #{status}
AND p.status = 'PUBLISHED'
AND p.visibility = 'PUBLIC'
AND ( p.title LIKE CONCAT('%', #{keyword}, '%') OR p.summary LIKE CONCAT('%', #{keyword}, '%') OR m.name LIKE CONCAT('%', #{keyword}, '%') OR EXISTS ( SELECT 1 FROM forum_post_tag search_pt INNER JOIN forum_tag search_t ON search_t.id = search_pt.tag_id WHERE search_pt.post_id = p.id AND search_t.name LIKE CONCAT('%', #{keyword}, '%') ) )
AND p.category_id = #{categoryId}
ORDER BY
p.is_top DESC, (p.view_count + p.like_count * 5 + p.favorite_count * 8) DESC, p.published_at DESC
p.is_top DESC, p.favorite_count DESC, p.published_at DESC
p.is_featured DESC, p.is_top DESC, p.published_at DESC
p.is_top DESC, p.published_at DESC, p.updated_at DESC

SELECT p.id, p.title, p.summary, p.cover_url AS coverUrl, p.published_at AS publishedAt, p.view_count AS viewCount, m.name AS authorName, c.name AS categoryName FROM forum_post p INNER JOIN member m ON m.id = p.author_id LEFT JOIN forum_category c ON c.id = p.category_id WHERE p.deleted = 0 AND p.status = 'PUBLISHED' AND p.id != #{excludeId} AND p.category_id = #{categoryId}
AND p.visibility = 'PUBLIC'
ORDER BY p.is_featured DESC, p.published_at DESC LIMIT 4
